inputs = ['wkwwf', 'jz', 'iwfw', 'gxfw', 'jhj']
outputs = ['wkwww', 'vzywiuedh', 'iwww', 'gxww', 'vzhvz']

# Let's manually compare each pair
for i in range(len(inputs)):
    inp = inputs[i]
    outp = outputs[i]
    print(f"Pair {i}: '{inp}' -> '{outp}'")

    # Find differences
    min_len = min(len(inp), len(outp))
    diff_positions = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_positions.append((j, inp[j], outp[j]))

    if len(outp) > len(inp):
        for j in range(len(inp), len(outp)):
            diff_positions.append((j, '_', outp[j]))
    elif len(inp) > len(outp):
        for j in range(len(outp), len(inp)):
            diff_positions.append((j, inp[j], '_'))

    print(f"  Differences: {diff_positions}")
    print()

